"""Prepare versioned SAULUX builds and publish the same binaries to OTA hosting."""

# AI: below section was generated by an AI
import argparse
import hashlib
import json
import re
import shutil
from pathlib import Path

RELEASES = ("SAULUX_2I2O", "SAULUX_5I4O", "SAULUX_ETHERNET")
OTA_BASE = "https://altdaps.github.io/WLED-SAULUX"
MAX_FIRMWARE_SIZE = 0x180000


def prepare(tag, root=Path(".")):
    """Use a validated fork tag as firmware version, asset version and build metadata."""
    match = re.fullmatch(r"saulux-v(\d+\.\d+\.\d+(?:-[0-9A-Za-z]+(?:[.-][0-9A-Za-z]+)*)?)", tag)
    if not match:
        raise ValueError("Expected tag saulux-vX.Y.Z (optional prerelease suffix)")
    package_file = root / "package.json"
    package = json.loads(package_file.read_text())
    package["version"] = match[1]
    package_file.write_text(json.dumps(package, indent=2) + "\n")
    return match[1]


def package(version, source, destination):
    """Fail if any target is missing or oversized; emit an atomic OTA release manifest."""
    destination.mkdir(parents=True, exist_ok=True)
    assets = []
    checksums = []
    for release in RELEASES:
        name = f"WLED_{version}_{release}.bin"
        binary = source / name
        data = binary.read_bytes()
        if not data or data[0] != 0xE9 or len(data) > MAX_FIRMWARE_SIZE:
            raise ValueError(f"Invalid or oversized ESP32 firmware: {name}")
        digest = hashlib.sha256(data).hexdigest()
        shutil.copyfile(binary, destination / name)
        assets.append({"name": name, "size": len(data), "sha256": digest,
                       "browser_download_url": f"{OTA_BASE}/{name}"})
        checksums.append(f"{digest}  {name}\n")
        factory = source / f"WLED_{version}_{release}_factory.bin"
        if factory.exists():
            shutil.copyfile(factory, destination / factory.name)
            checksums.append(f"{hashlib.sha256(factory.read_bytes()).hexdigest()}  {factory.name}\n")
    (destination / "manifest.json").write_text(json.dumps({"tag_name": f"v{version}", "assets": assets}, indent=2) + "\n")
    (destination / "SHA256SUMS").write_text("".join(checksums))
    (destination / ".nojekyll").touch()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    commands = parser.add_subparsers(dest="command", required=True)
    prep = commands.add_parser("prepare")
    prep.add_argument("tag")
    pack = commands.add_parser("package")
    pack.add_argument("--source", type=Path, default=Path("build_output/release"))
    pack.add_argument("--destination", type=Path, default=Path("dist"))
    args = parser.parse_args()
    if args.command == "prepare":
        print(prepare(args.tag))
    else:
        version = json.loads(Path("package.json").read_text())["version"]
        package(version, args.source, args.destination)


if __name__ == "__main__":
    main()
